const baseUrl = pm.collectionVariables.get("base_url");
const apiKey = pm.collectionVariables.get("api_key");

// Limpiar datos de ejecuciones anteriores
pm.collectionVariables.unset("cuenta_id");
pm.collectionVariables.unset("saldo_inicial");

const consulta = {
    url: baseUrl + "/api/v2/sql/select",
    method: "POST",
    header: {
        "Content-Type": "application/json",
        "x-api-key": apiKey
    },
    body: {
        mode: "raw",
        raw: JSON.stringify({
            sql: "SELECT id, saldo FROM cuentas WHERE estado = $1 AND activa = $2 ORDER BY id ASC LIMIT 1",
            params: ["activa", true]
        })
    }
};

// Consulta SQL previa, compatible con Newman
pm.sendRequest(consulta, function (error, respuesta) {
    if (error) {
        console.error("Fallo en el Pre-request:", error.message);
        pm.execution.skipRequest();
        return;
    }

    if (respuesta.code !== 200) {
        console.error("Error SQL:", respuesta.code);
        pm.execution.skipRequest();
        return;
    }

    try {
        const resultado = respuesta.json();

        if (!Array.isArray(resultado.data) ||
            resultado.data.length === 0) {
            throw new Error("No se encontraron cuentas activas");
        }

        const cuenta = resultado.data[0];

        pm.collectionVariables.set("cuenta_id", cuenta.id);
        pm.collectionVariables.set("saldo_inicial", cuenta.saldo);

        console.log("Cuenta seleccionada:", cuenta.id);
        console.log("Saldo inicial:", cuenta.saldo);

    } catch (error) {
        console.error("Fallo en el Pre-request:", error.message);
        pm.execution.skipRequest();
    }
});

const baseUrl = pm.collectionVariables.get("base_url");
const apiKey = pm.collectionVariables.get("api_key");
const cuentaId = Number(pm.collectionVariables.get("cuenta_id"));
const saldoInicial = Number(pm.collectionVariables.get("saldo_inicial"));
const monto = 1000;

pm.test("POST devuelve 201 Created", function () {
    pm.response.to.have.status(201);
});

if (pm.response.code === 201) {

    const resultado = pm.response.json();
    const movimiento = resultado.data;

    pm.test("Movimiento registrado en la cuenta correcta", function () {
        pm.expect(Number(movimiento.cuenta_id)).to.eql(cuentaId);
        pm.expect(movimiento.tipo).to.eql("credito");
        pm.expect(Number(movimiento.monto)).to.eql(monto);
        pm.expect(movimiento.id).to.exist;
    });

    const movimientoId = Number(movimiento.id);

    const consultaSQL = (sql, params) => ({
        url: baseUrl + "/api/v2/sql/select",
        method: "POST",
        header: {
            "Content-Type": "application/json",
            "x-api-key": apiKey
        },
        body: {
            mode: "raw",
            raw: JSON.stringify({ sql, params })
        }
    });

    // Validar el movimiento insertado
    pm.sendRequest(
        consultaSQL(
            "SELECT id, cuenta_id, tipo, monto, saldo_posterior, activo FROM movimientos WHERE id = $1",
            [movimientoId]
        ),
        function (error, response) {
            pm.test("SQL: movimiento insertado correctamente", function () {
                pm.expect(error).to.equal(null);
                pm.expect(response.code).to.eql(200);

                const filas = response.json().data;
                pm.expect(filas).to.be.an("array").with.lengthOf(1);

                const fila = filas[0];

                pm.expect(Number(fila.id)).to.eql(movimientoId);
                pm.expect(Number(fila.cuenta_id)).to.eql(cuentaId);
                pm.expect(fila.tipo).to.eql("credito");
                pm.expect(Number(fila.monto)).to.eql(monto);
                pm.expect(fila.activo).to.eql(true);
                pm.expect(Number(fila.saldo_posterior))
                    .to.be.closeTo(saldoInicial + monto, 0.001);
            });
        }
    );

    // Validar el saldo actualizado
    pm.sendRequest(
        consultaSQL(
            "SELECT id, saldo FROM cuentas WHERE id = $1",
            [cuentaId]
        ),
        function (error, response) {
            pm.test("SQL: saldo de la cuenta actualizado", function () {
                pm.expect(error).to.equal(null);
                pm.expect(response.code).to.eql(200);

                const filas = response.json().data;
                pm.expect(filas).to.be.an("array").with.lengthOf(1);

                const saldoFinal = Number(filas[0].saldo);
                const saldoEsperado = saldoInicial + monto;

                console.log("Saldo inicial:", saldoInicial);
                console.log("Movimiento:", monto);
                console.log("Saldo esperado:", saldoEsperado);
                console.log("Saldo final:", saldoFinal);

                pm.expect(saldoFinal)
                    .to.be.closeTo(saldoEsperado, 0.001);
            });
        }
    );
}

const baseUrl = pm.collectionVariables.get("base_url");
const apiKey = pm.collectionVariables.get("api_key");

// Limpiar datos anteriores
pm.collectionVariables.unset("cuenta_id");
pm.collectionVariables.unset("saldo_inicial");
pm.collectionVariables.unset("movimientos_antes");

// Primera consulta: obtener una cuenta activa
const consulta = {
    url: baseUrl + "/api/v2/sql/select",
    method: "POST",
    header: {
        "Content-Type": "application/json",
        "x-api-key": apiKey
    },
    body: {
        mode: "raw",
        raw: JSON.stringify({
            sql: "SELECT id, saldo FROM cuentas WHERE estado = $1 AND activa = $2 ORDER BY id ASC LIMIT 1",
            params: ["activa", true]
        })
    }
};

function detener(error) {
    console.error("Fallo en el Pre-request:", error);
    pm.execution.skipRequest();
}

pm.sendRequest(consulta, function (error, respuesta) {
    if (error) {
        detener(error.message);
        return;
    }

    try {
        if (respuesta.code !== 200) {
            throw new Error("Error SQL: " + respuesta.code);
        }

        const resultado = respuesta.json();

        if (!Array.isArray(resultado.data) ||
            resultado.data.length === 0) {
            throw new Error("No se encontraron cuentas activas");
        }

        const cuenta = resultado.data[0];

        pm.collectionVariables.set("cuenta_id", cuenta.id);
        pm.collectionVariables.set("saldo_inicial", cuenta.saldo);

        // Segunda consulta: contar movimientos existentes
        const consultaConteo = {
            url: baseUrl + "/api/v2/sql/select",
            method: "POST",
            header: {
                "Content-Type": "application/json",
                "x-api-key": apiKey
            },
            body: {
                mode: "raw",
                raw: JSON.stringify({
                    sql: "SELECT COUNT(*) AS total FROM movimientos WHERE cuenta_id = $1",
                    params: [Number(cuenta.id)]
                })
            }
        };

        pm.sendRequest(consultaConteo, function (errorConteo, respuestaConteo) {
            if (errorConteo) {
                detener(errorConteo.message);
                return;
            }

            try {
                if (respuestaConteo.code !== 200) {
                    throw new Error("Error al contar movimientos: " + respuestaConteo.code);
                }

                const datosConteo = respuestaConteo.json();

                if (!Array.isArray(datosConteo.data) ||
                    datosConteo.data.length !== 1) {
                    throw new Error("Respuesta SQL de conteo inválida");
                }

                pm.collectionVariables.set(
                    "movimientos_antes",
                    datosConteo.data[0].total
                );

                console.log("Movimientos antes:", datosConteo.data[0].total);
                console.log("Cuenta seleccionada:", cuenta.id);
                console.log("Saldo inicial:", cuenta.saldo);

            } catch (error) {
                detener(error.message);
            }
        });

    } catch (error) {
        detener(error.message);
    }
});

const baseUrl = pm.collectionVariables.get("base_url");
const apiKey = pm.collectionVariables.get("api_key");

const cuentaId = Number(
    pm.collectionVariables.get("cuenta_id")
);

const saldoInicial = Number(
    pm.collectionVariables.get("saldo_inicial")
);

const movimientosAntes = Number(
    pm.collectionVariables.get("movimientos_antes")
);

// 1. Validar que la API rechace el monto negativo
pm.test("POST rechaza monto negativo con 400", function () {
    pm.response.to.have.status(400);
});

// Función para consultar la base de datos
function consultaSQL(sql, params) {
    return {
        url: baseUrl + "/api/v2/sql/select",
        method: "POST",
        header: {
            "Content-Type": "application/json",
            "x-api-key": apiKey
        },
        body: {
            mode: "raw",
            raw: JSON.stringify({ sql, params })
        }
    };
}

// 2. Verificar que el saldo no cambió
pm.sendRequest(
    consultaSQL(
        "SELECT saldo FROM cuentas WHERE id = $1",
        [cuentaId]
    ),
    function (error, response) {

        pm.test("SQL: saldo permanece sin cambios", function () {
            pm.expect(error).to.equal(null);
            pm.expect(response.code).to.eql(200);

            const filas = response.json().data;

            pm.expect(filas).to.be.an("array")
                .with.lengthOf(1);

            const saldoFinal = Number(filas[0].saldo);

            console.log("Saldo antes:", saldoInicial);
            console.log("Saldo después:", saldoFinal);

            pm.expect(saldoFinal)
                .to.be.closeTo(saldoInicial, 0.001);
        });
    }
);

// 3. Verificar que no se insertaron movimientos
pm.sendRequest(
    consultaSQL(
        "SELECT COUNT(*) AS total FROM movimientos WHERE cuenta_id = $1",
        [cuentaId]
    ),
    function (error, response) {

        pm.test("SQL: no se insertaron movimientos", function () {
            pm.expect(error).to.equal(null);
            pm.expect(response.code).to.eql(200);

            const filas = response.json().data;

            pm.expect(filas).to.be.an("array")
                .with.lengthOf(1);

            const movimientosDespues = Number(
                filas[0].total
            );

            console.log("Movimientos antes:", movimientosAntes);
            console.log("Movimientos después:", movimientosDespues);

            pm.expect(movimientosDespues)
                .to.eql(movimientosAntes);
        });
    }
);
